import Foundation

extension DigitalGuides {
    static let onlineServices = DirectoryGuide(
        cardSummary: .init(ukrainian: "Державні заяви, податки, медичні дані й електронна пошта", german: "Amtswege, Steuern, Gesundheitsdaten und elektronische Post"),
        introduction: .init(ukrainian: "Почніть з офіційного каталогу, а потім перейдіть до потрібного сервісу. Вхід, подання заяви та отримання відповіді — різні кроки.", german: "Im amtlichen Katalog beginnen und zum passenden Dienst wechseln. Anmeldung, Antrag und Zustellung sind unterschiedliche Schritte."),
        sections: [
            .init("find", "magnifyingglass", "Знайдіть потрібну послугу", "Passenden Dienst finden", "На oesterreich.gv.at відкрийте «Digitale Services» й знайдіть послугу за життєвою ситуацією: зміна адреси, витяг із реєстру, заява або підпис PDF. На сторінці самої процедури звірте відповідальну установу, документи, можливу плату та спосіб входу — ID Austria чи EU Login. Якщо онлайн-послуги для вашого випадку немає, перевірте особистий або поштовий шлях.", "Auf oesterreich.gv.at unter „Digitale Services“ nach Lebenslage suchen: Wohnsitzänderung, Registerauszug, Antrag oder PDF-Signatur. Auf der Verfahrensseite zuständige Stelle, Unterlagen, mögliche Gebühr und Anmeldung per ID Austria oder EU Login prüfen. Falls es für den Fall keinen Onlineweg gibt, persönliche oder postalische Einbringung prüfen.", source: catalog),
            .init("submit", "doc.badge.arrow.up", "Подайте заяву й збережіть доказ", "Antrag einbringen und Nachweis sichern", "Перед відправленням перевірте особисті дані, вкладення, адресата й строк. Після відправлення збережіть підтвердження, номер справи та копію поданих даних; сам вхід до порталу ще не означає, що заяву подано. Якщо підтвердження немає, перевірте статус у кабінеті й зверніться до відповідальної установи до кінця строку.", "Vor dem Absenden Personendaten, Beilagen, Empfänger und Frist prüfen. Danach Bestätigung, Geschäftszahl und Kopie der Eingaben sichern; die bloße Anmeldung am Portal ist noch keine Antragstellung. Fehlt eine Bestätigung, Status im Konto prüfen und vor Fristende die zuständige Stelle kontaktieren.", source: onlineProcesses),
            .init("finance", "eurosign", "Податки: FinanzOnline", "Steuern: FinanzOnline", "Для податкових заяв відкрийте FinanzOnline через bmf.gv.at і увійдіть з ID Austria. При першому вході може знадобитися номер соціального страхування або податковий номер для зіставлення даних. Перевіряйте повідомлення й рішення саме в FinanzOnline; не припускайте, що вони з’являться лише в «Mein Postkorb». Вхід із ID Austria не потребує окремої реєстрації в FinanzOnline.", "Für Steuersachen FinanzOnline über bmf.gv.at öffnen und mit ID Austria anmelden. Beim ersten Einstieg kann für die Zuordnung die Sozialversicherungs- oder Steuernummer nötig sein. Nachrichten und Bescheide auch direkt in FinanzOnline prüfen; nicht annehmen, dass alles nur in „Mein Postkorb“ erscheint. Für den ID-Austria-Einstieg ist keine gesonderte FinanzOnline-Registrierung nötig.", source: finance),
            .init("finance-access", "key", "Якщо втратили доступ до FinanzOnline", "Wenn FinanzOnline nicht mehr zugänglich ist", "Спочатку перевірте, чи можете увійти через ID Austria: старі дані FinanzOnline для цього не потрібні. З 1 жовтня 2026 року онлайн-самовідновлення старих даних доступу для приватних осіб припинено. Якщо проблемою є пароль ID Austria, використайте офіційне відновлення ID Austria; якщо обліковий запис заблоковано, оберіть відповідний шлях у довідці BMF.", "Zuerst den Einstieg mit ID Austria versuchen; bisherige FinanzOnline-Kennungen sind dafür nicht nötig. Seit 1. Oktober 2026 ist die bisherige Online-Selbstrücksetzung alter Kennungen für Privatpersonen eingestellt. Betrifft das Problem das ID-Austria-Signatur-Passwort, dessen amtliche Wiederherstellung nutzen; bei gesperrtem FinanzOnline-Zugang den passenden Weg in der BMF-Anmeldehilfe wählen.", source: financeRecovery),
            .init("health", "cross.case", "Медичні дані: ELGA", "Gesundheitsdaten: ELGA", "На gesundheit.gv.at увійдіть до порталу ELGA з ID Austria. Там можна переглянути наявні eBefunde й eMedikation, а також налаштувати участь і доступ. Якщо ID Austria немає, зверніться до ELGA-Ombudsstelle або eHealth-Servicestelle; технічну допомогу надає ELGA-Serviceline. Відсутній запис не замінює роз’яснення лікаря й не доводить, що обстеження не було.", "Über gesundheit.gv.at mit ID Austria beim ELGA-Portal anmelden. Dort vorhandene eBefunde und eMedikation einsehen sowie Teilnahme und Zugriffe verwalten. Ohne ID Austria an ELGA-Ombudsstelle oder eHealth-Servicestelle wenden; technische Hilfe bietet die ELGA-Serviceline. Ein fehlender Eintrag ersetzt keine ärztliche Auskunft und beweist nicht, dass keine Untersuchung stattfand.", source: elga),
            .init("postbox", "envelope.badge", "Офіційні повідомлення: Mein Postkorb", "Behördenpost: Mein Postkorb", "Для електронного отримання листів зареєструйте «Mein Postkorb» на oesterreich.gv.at з ID Austria та підтвердьте email. Перевіряйте скриньку напряму й тримайте email актуальним: повідомлення може потрапити до спаму. Лист із підтвердженням доставки може вважатися врученим уже першого робочого дня після email-сповіщення, навіть якщо ви відкрили його пізніше; одразу збережіть документ і перевірте строк відповіді.", "Für elektronische Behördenpost „Mein Postkorb“ auf oesterreich.gv.at mit ID Austria registrieren und E-Mail bestätigen. Postkorb direkt prüfen und E-Mail aktuell halten; Hinweise können im Spam landen. Eine nachweisliche Zustellung kann bereits am ersten Werktag nach der E-Mail-Verständigung wirksam sein, auch wenn Sie später öffnen; Dokument sofort sichern und Antwortfrist prüfen.", source: delivery),
            .init("sign", "signature", "Підпишіть PDF лише за потреби", "PDF nur bei Bedarf signieren", "Якщо установа просить підписаний PDF, відкрийте офіційний сервіс «PDF Signatur» на oesterreich.gv.at, завантажте документ і підтвердьте підпис через ID Austria. Завантажте вже підписаний файл та перевірте його перед надсиланням. Підпис є юридично значущим, тому не підтверджуйте невідомий документ; також перевірте, чи установа взагалі приймає PDF замість власної онлайн-форми.", "Verlangt eine Stelle ein signiertes PDF, amtlichen Dienst „PDF Signatur“ auf oesterreich.gv.at öffnen, Dokument hochladen und mit ID Austria signieren. Signierte Datei herunterladen und vor Versand prüfen. Die Signatur ist rechtlich verbindlich: kein unbekanntes Dokument bestätigen und klären, ob die Stelle ein PDF statt ihres Onlineformulars akzeptiert.", source: pdfSignature)
        ], sources: [catalog, onlineProcesses, finance, financeRecovery, elga, postbox, delivery, pdfSignature]
    )
}
